/* Démonstration guidée, lecture seule : aucune création de dossier ni écriture API. */
(()=>{
'use strict';
const D=window.CREDIT_DEMO_DATA, $=s=>document.querySelector(s), root=()=>$('#view');
const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v===null||v===undefined?'Non disponible':new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(Number(v))+' FCFA';
const date=v=>{try{return new Intl.DateTimeFormat('fr-FR',{month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(v.length===7?v+'-01':v))}catch{return v}};
const label=s=>({favorable:'Favorable',vigilance:'Vigilance',defavorable:'Point de vigilance',incomplet:'À compléter'}[s]||s||'Non déterminé');
const badge=s=>'<span class="demo-status demo-'+esc(s)+'">'+esc(label(s))+'</span>';
const go=h=>{location.hash=h;window.scrollTo(0,0)};
const cases=()=>Object.values(D.cases), stages=['Dossier','Données financières','Documents','Analyse v2','Simulation','Restitution'];
function launcher(){return '<section class="demo-launch"><div><span class="demo-kicker">DÉMONSTRATION GUIDÉE</span><h2>Découvrez Crédix en situation.</h2><p>Deux dossiers fictifs, de la constitution à l’analyse et aux simulations. Sans inscription et sans modification de vos dossiers.</p></div><a class="demo-launch-link" href="#demo">Lancer la démonstration <span>↗</span></a></section>'}
function decorateOverview(){const v=root();if(!v||v.querySelector('.demo-launch'))return;const s=v.querySelector('.stories');if(s)s.insertAdjacentHTML('afterend',launcher());else v.insertAdjacentHTML('afterbegin',launcher())}
function landing(){
 $('#page-title').textContent='Crédix, en démonstration.';$('#page-subtitle').textContent='Parcourez deux dossiers synthétiques et découvrez chaque étape de l’analyse financière.';
 root().innerHTML='<section class="demo-intro"><span class="demo-kicker">ENVIRONNEMENT DE DÉMONSTRATION · DONNÉES FICTIVES</span><h2>Deux profils. Deux lectures financières.</h2><p>Suivez le même parcours de bout en bout : informations du demandeur, données financières, qualité documentaire, analyse déterministe, simulation et restitution.</p><div class="demo-warning"><strong>Important</strong><span>Les montants et rapports proviennent des exemples synthétiques du dépôt. Les politiques utilisées sont illustratives et non approuvées. Aucun score actif, aucune probabilité de défaut et aucune décision de financement ne sont produits.</span></div></section><div class="demo-cases">'+cases().map(c=>'<article class="demo-case-card"><div class="demo-card-top"><span>'+(c.core==='individuals'?'PARTICULIER':'ENTREPRISE')+'</span><span class="demo-number">'+(c.core==='individuals'?'01':'02')+'</span></div><h3>'+esc(c.title)+'</h3><p>'+esc(c.subtitle)+'</p><div class="demo-card-metric"><small>'+(c.core==='individuals'?'Revenus mensuels déclarés':'Encaissements · période 1')+'</small><strong>'+money(c.core==='individuals'?c.inputs[0].income:c.inputs[0].receipts)+'</strong></div><div class="demo-card-metric"><small>Financement demandé</small><strong>'+money(c.requested_loan)+'</strong></div><div class="demo-card-bottom">'+badge(c.scoring.qualification)+'<a href="#demo/'+c.id+'/0">Explorer ce parcours ↗</a></div></article>').join('')+'</div><div class="demo-footnote">Mode lecture seule · Aucun dossier réel n’est créé, transmis ou enregistré.</div><a class="demo-back-home" href="#overview">← Retour à l’accueil</a>';
}
function shell(c,n,content){
 $('#page-title').textContent=c.title;$('#page-subtitle').textContent='Parcours de démonstration · '+c.subtitle;
 root().innerHTML='<div class="demo-topline"><a href="#demo">← Choisir un autre cas</a><span>DONNÉES SYNTHÉTIQUES · LECTURE SEULE</span></div><div class="demo-progress">'+stages.map((s,i)=>'<button type="button" data-demo-step="'+i+'" class="'+(i===n?'active':i<n?'done':'')+'" aria-current="'+(i===n?'step':'false')+'"><i>'+(i<n?'✓':i+1)+'</i><span>'+s+'</span></button>').join('')+'</div><div class="demo-stage">'+content+'</div><div class="demo-controls"><button type="button" class="demo-prev" '+(n===0?'disabled':'')+' data-demo-nav="'+(n-1)+'">← Précédent</button><span>Étape '+(n+1)+' / 6</span>'+(n===5?'<button type="button" class="demo-next" data-demo-home>Terminer la visite ↗</button>':'<button type="button" class="demo-next" data-demo-nav="'+(n+1)+'">Étape suivante →</button>')+'</div><div class="demo-disclaimer">Cette démonstration est indépendante de votre espace connecté. Elle ne crée ni ne modifie aucun dossier.</div>';
 root().querySelectorAll('[data-demo-nav],[data-demo-step]').forEach(b=>b.addEventListener('click',()=>go('#demo/'+c.id+'/'+(b.dataset.demoNav??b.dataset.demoStep))));
 root().querySelector('[data-demo-home]')?.addEventListener('click',()=>go('#demo'));
 root().querySelector('[data-demo-print]')?.addEventListener('click',()=>window.print());
}
function panel(title,body,extra){return '<section class="demo-panel '+(extra||'')+'"><span class="demo-label">'+title+'</span>'+body+'</section>'}
function kpis(items){return '<div class="demo-kpi-row">'+items.map(x=>'<div><small>'+x[0]+'</small><strong class="'+(x[2]||'')+'">'+x[1]+'</strong></div>').join('')+'</div>'}
function note(title,text){return '<div class="demo-note"><strong>'+title+'</strong><p>'+text+'</p></div>'}
function dossier(c){
 const individual=c.core==='individuals';
 return '<div class="demo-stage-heading"><span class="demo-kicker">01 · CONSTITUTION DU DOSSIER</span><h2>Comprendre la demande avant de calculer.</h2><p>Le moteur reçoit un dossier structuré, avec les informations connues et les éléments restant à confirmer.</p></div><div class="demo-profile-grid">'+panel('PROFIL DU DEMANDEUR','<h3>'+esc(c.name)+'</h3><dl><div><dt>Catégorie</dt><dd>'+esc(c.profile)+'</dd></div>'+(c.activity?'<div><dt>Activité</dt><dd>'+esc(c.activity)+'</dd></div>':'')+'<div><dt>Date de référence</dt><dd>'+esc(date(c.as_of))+'</dd></div><div><dt>Classification</dt><dd><span class="demo-chip">Dossier synthétique</span></dd></div></dl>')+panel('BESOIN DE FINANCEMENT','<div class="demo-big-number">'+money(c.requested_loan)+'</div><p>Montant demandé</p><dl><div><dt>Besoin justifié déclaré</dt><dd>'+money(c.justified_need)+'</dd></div><div><dt>'+(individual?'Réserve mobilisable déclarée':'Trésorerie d’ouverture')+'</dt><dd>'+money(individual?c.reserve:c.opening_cash)+'</dd></div></dl>','demo-panel-dark')+'</div>'+note('Ce que cette étape démontre','Le dossier distingue le profil, le besoin, les dettes et les données financières. Les valeurs non documentées ne sont pas automatiquement complétées.');
}
function finances(c){
 const individual=c.core==='individuals';
 const headers=individual?['Période','Revenu net','Charges essentielles']:['Période','Encaissements','Charges d’exploitation','Taxes','Retraits ménage'];
 const rows=c.inputs.map(p=>'<tr><td>'+date(p.period)+'</td>'+(individual?'<td>'+money(p.income)+'</td><td>'+money(p.essential_expenses)+'</td>':'<td>'+money(p.receipts)+'</td><td>'+money(p.operating_expenses)+'</td><td>'+money(p.taxes)+'</td><td>'+money(p.household_withdrawals)+'</td>')+'</tr>').join('');
 const table='<div class="demo-table-wrap"><table class="demo-table"><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows+'</tbody></table></div>';
 const extra=individual?note('Historique déclaré',c.income_history.length+' périodes historiques sont présentes dans cet exemple. Revenu observé : '+money(c.income_history[0]?.value)+' par période.'):'<div class="demo-table-wrap"><table class="demo-table"><thead><tr><th>Période comptable</th><th>Chiffre d’affaires</th><th>Charges d’exploitation</th><th>Résultat net déclaré</th></tr></thead><tbody>'+c.accounting.map(a=>'<tr><td>'+date(a.period)+'</td><td>'+money(a.turnover)+'</td><td>'+money(a.operating_expenses)+'</td><td>'+money(a.net_result)+'</td></tr>').join('')+'</tbody></table></div>'+note('Lecture essentielle','Le résultat comptable et la trésorerie sont deux notions différentes. Le moteur examine les flux disponibles à chaque échéance.');
 return '<div class="demo-stage-heading"><span class="demo-kicker">02 · DONNÉES FINANCIÈRES</span><h2>'+(individual?'Revenus, charges et dettes.':'Encaissements, dépenses et cycle d’activité.')+'</h2><p>Les périodes restent visibles séparément : une bonne moyenne ne masque pas un mois déficitaire.</p></div>'+kpis([[individual?'Revenu net mensuel':'Trésorerie d’ouverture',money(individual?c.inputs[0].income:c.opening_cash)],[individual?'Réserve déclarée':'Besoin financé déclaré',money(individual?c.reserve:c.justified_need)],['Financement demandé',money(c.requested_loan)]])+table+extra;
}
function documents(c){
 const q=c.documentary_quality,v=q.coverage,expected=c.core==='individuals'?['Pièce d’identité et cohérence de l’état civil','Bulletins de salaire et preuve de continuité des revenus','Relevés de compte couvrant les périodes analysées','Échéanciers des crédits existants']:['RCCM, IFU et pouvoirs du représentant','États financiers et pièces comptables comparables','Relevés bancaires et rapprochement des flux','Balance âgée des créances et dettes fournisseurs','Échéanciers des emprunts et justificatifs des garanties'];
 const rows=[['Référence de preuve synthétique','Source déclarée · aucune pièce réelle jointe','favorable'],['Authenticité',q.authenticity_status==='not_assessed'?'Non évaluée dans cet exemple':'État : '+q.authenticity_status,'incomplet'],['Couverture documentaire',v.controlled_amounts+' montant(s) contrôlé(s) sur '+v.important_amounts+' montant(s) importants','vigilance']];
 return '<div class="demo-stage-heading"><span class="demo-kicker">03 · PIÈCES & QUALITÉ DOCUMENTAIRE</span><h2>La qualité des preuves est distincte du résultat financier.</h2><p>Les montants doivent être reliés à leurs sources et conserver leurs réserves de vérification.</p></div>'+kpis([['Montants importants',v.important_amounts],['Montants utilisables',v.usable_amounts],['Montants contrôlés',v.controlled_amounts]])+'<div class="demo-doc-status">'+rows.map(x=>'<div><span class="demo-doc-icon">•</span><div><strong>'+x[0]+'</strong><small>'+esc(x[1])+'</small></div>'+badge(x[2])+'</div>').join('')+'</div>'+panel('PIÈCES À RÉUNIR POUR UN DOSSIER RÉEL','<ul class="demo-check-list">'+expected.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>')+note('Limite explicite de cette démonstration','Les jeux financiers comportent des références de preuve synthétiques, mais aucun document réel n’a été téléversé ou authentifié dans ce parcours guidé. Dans un dossier réel, l’import, l’OCR, le rattachement aux périodes et la revue humaine doivent être effectués.');
}
function analysis(c){
 const individual=c.core==='individuals',headers=individual?['Période','Revenu net','Disponible avant dette','Dette existante','Nouvelle dette','Marge après crédit','Réserve projetée']:['Période','Encaissements','Disponible pour dette','Dette existante','Nouvelle dette','Marge après dette','Trésorerie finale'];
 const rows=c.periods.map(p=>'<tr><td>'+date(p.period)+'</td><td>'+money(p.primary)+'</td><td>'+money(p.available)+'</td><td>'+money(p.existing_debt)+'</td><td>'+money(p.new_debt)+'</td><td class="'+(Number(p.margin)<0?'negative':'positive')+'">'+money(p.margin)+'</td><td class="'+(Number(p.balance)<0?'negative':'positive')+'">'+money(p.balance)+'</td></tr>').join('');
 const sections=c.sections.map(s=>'<div><span>'+esc(s.title)+'</span>'+badge(s.status)+'</div>').join('');
 return '<div class="demo-stage-heading"><span class="demo-kicker">04 · MOTEUR FINANCIER V2</span><h2>Une lecture période par période.</h2><p>'+esc(c.summary)+'</p></div>'+kpis([['Marge minimale',money(c.minimum_margin),Number(c.minimum_margin)<0?'negative':''],[individual?'Réserve minimale':'Trésorerie minimale',money(c.minimum_balance),Number(c.minimum_balance)<0?'negative':''],['Périodes déficitaires',c.deficits.length]])+'<div class="demo-table-wrap"><table class="demo-table"><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows+'</tbody></table></div>'+panel('SOUS-ANALYSES DU MOTEUR','<div class="demo-section-list">'+sections+'</div>')+note('Interprétation',individual?'Dans les flux de base fournis, la marge reste positive. La dépendance à une source de revenu et la résistance à une baisse doivent néanmoins être examinées.':'Ce cas illustre un point important : une rentabilité comptable déclarée n’empêche pas une tension de trésorerie et une marge négative sur une période.');
}
function simulations(c){
 const s=c.stress[0],individual=c.core==='individuals';
 const reverse=c.reverse_tests.map(t=>'<div class="demo-reverse"><div><strong>'+(t.parameter==='revenue_drop'?'Baisse de revenus annulant la marge':'Échéance additionnelle annulant la marge')+'</strong><small>'+esc(t.notice)+'</small></div><strong>'+(t.status==='found'?(t.parameter==='revenue_drop'?(Number(t.threshold)*100).toFixed(2)+' %':money(t.threshold)):'Déjà dépassé')+'</strong></div>').join('');
 const variants=c.variants.map(v=>'<div><div><strong>'+v.months+' mois · '+money(v.principal)+'</strong><span class="demo-status '+(v.compatible?'demo-favorable':'demo-defavorable')+'">'+(v.compatible?'Compatible sous hypothèses':'Non compatible / incomplet')+'</span></div><small>Remboursement total : '+money(v.total_repayment)+' · Coût : '+money(v.cost)+'</small>'+(v.information_requested?.length?'<small>À fournir : '+esc(v.information_requested.join(' ; '))+'</small>':'')+'</div>').join('');
 return '<div class="demo-stage-heading"><span class="demo-kicker">05 · SIMULATIONS & RECHERCHES INVERSÉES</span><h2>Tester ce qui se passe si les hypothèses changent.</h2><p>Les scénarios sont des hypothèses de travail. Ils ne prédisent pas un défaut et ne constituent pas une recommandation automatique.</p></div>'+panel('SCÉNARIO · BAISSE DES FLUX DE 20%','<h3>'+esc(s.name)+'</h3><div class="demo-compare"><div><small>Marge minimale · référence</small><strong>'+money(s.before)+'</strong></div><div><small>Marge minimale · scénario</small><strong class="'+(Number(s.after)<0?'negative':'positive')+'">'+money(s.after)+'</strong></div></div><p class="demo-note-inline">Trésorerie / réserve minimale : '+money(s.balance_before)+' avant et '+money(s.balance_after)+' après le choc.</p>')+panel('RECHERCHE INVERSE',reverse)+panel('VARIANTES DE FINANCEMENT TESTÉES','<div class="demo-variants">'+variants+'</div>')+note('Ce que montre la simulation',individual?'Un allongement peut réduire l’échéance mais augmenter le coût total. Les deux dimensions doivent être comparées.':'La simulation ne fait pas disparaître le déficit observé. Les alternatives testées ne sont pas compatibles ou nécessitent des projections supplémentaires.');
}
function restitution(c){
 const individual=c.core==='individuals';
 return '<div class="demo-stage-heading"><span class="demo-kicker">06 · RESTITUTION</span><h2>La conclusion doit rester proportionnée aux preuves.</h2><p>Le rapport synthétise les constats, les limites et les informations nécessaires à la suite du dossier.</p></div><div class="demo-final-status"><span class="demo-label">ÉTAT OPÉRATIONNEL DU DOSSIER</span><h3>'+(individual?'Dossier à compléter':'Revue approfondie requise')+'</h3><p>'+esc(c.summary)+'</p></div><div class="demo-final-grid">'+panel('POINTS À RETENIR','<ul class="demo-check-list">'+c.alerts.slice(0,6).map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>')+panel('INFORMATIONS À COMPLÉTER','<ul class="demo-check-list">'+c.missing_information.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>')+'</div>'+panel('STATUT DE LA QUALIFICATION','<div class="demo-final-score"><strong>Score : non disponible</strong><span>Modèle statistique : désactivé</span><span>Politique : '+esc(c.scoring.policy_status)+'</span><span>Décision prêteur : aucune décision enregistrée</span></div><p>Aucune probabilité de défaut (PD) ni perte attendue n’est calculée. La décision finale relève exclusivement du partenaire financier habilité, après revue des éléments manquants.</p>','demo-panel-dark')+'<div class="demo-print-row"><button type="button" class="demo-print" data-demo-print>Imprimer cette démonstration ↗</button><a href="#demo">Revenir aux deux parcours →</a></div>';
}
function render(hash){
 if(!D){landing();return}
 const b=hash.split('/');if(b.length===1){landing();return}
 const c=D.cases[b[1]];if(!c){landing();return}
 const n=Math.max(0,Math.min(5,Number(b[2]||0)));
 shell(c,n,[dossier,finances,documents,analysis,simulations,restitution][n](c));
}
window.CreditDemo={decorateOverview,render};
if(location.hash==='#demo'||location.hash.startsWith('#demo/'))window.renderApp?.();else if(location.hash===''||location.hash==='#overview')window.CreditDemo.decorateOverview();
})();